SELECT COUNT(*) AS boundary_buys, SUM(f.id IS NOT NULL) AS newer5m_inserted_before_fill, SUM(f.id IS NOT NULL AND f.decision NOT IN ('BUY','STRONG_BUY')) AS newer5m_not_bullish FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' LEFT JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time=o.candle_open_time - INTERVAL 4 MINUTE AND f.generated_at > o.generated_at AND f.created_at <= w.executed_at WHERE w.side='BUY' AND MOD(MINUTE(o.candle_open_time),5)=4 AND w.executed_at BETWEEN '2026-10-10 00:00:00' AND '2026-10-17 10:00:00';
SELECT w.id, w.symbol, w.execution_reason, o.id AS sig1m, f.id AS newer5m, f.decision AS newer5m_decision, w.executed_at FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' JOIN crypto_ai.trade_signal f ON f.symbol=o.symbol AND f.interval_code='5m' AND f.candle_open_time=o.candle_open_time - INTERVAL 4 MINUTE AND f.generated_at > o.generated_at AND f.created_at <= w.executed_at WHERE w.side='BUY' AND w.executed_at BETWEEN '2026-10-10 00:00:00' AND '2026-10-17 10:00:00' ORDER BY w.executed_at LIMIT 100;